  /// Tags of the items the active profile may see, by name.
  Future<List<CoreTag>> tags();

  /// The lyrics stored with the file `rel_path` of source `source_id`
  /// (as in `CoreItem`): embedded tags and the `.lrc` next to it. A file
  /// without lyrics gives an empty result; fails with `unavailable` when
  /// the source cannot be reached.
  Future<CoreTrackLyrics> trackLyrics({
    required PlatformInt64 sourceId,
    required String relPath,
  });

  Future<List<CoreItem>> tracks();

  /// The trailer of movie or show `item_id`, or `None` (then the page
  /// shows its slowly moving backdrop). Blocks on TMDB when it is asked;
  /// a TMDB failure is "no trailer", not an error.
  Future<CoreTrailer?> trailer({
    required String itemId,
    required CoreTrailerRequest request,
  });

  /// Unlocks a library with its PIN or password (shared wrong-PIN
  /// backoff).
  Future<CorePinVerdict> unlockPersonalLibrary({
    required PlatformInt64 id,
    required String secret,
  });

  /// Replaces the settings of a profile; the active one applies them at
  /// once.
  Future<CoreProfile> updateProfile({
    required PlatformInt64 id,
    required CoreProfileSettings settings,
    String? parentToken,
  });

  Future<void> updateShelf({
    required PlatformInt64 id,
    required String name,
    required CoreLibraryQuery query,
    required bool pinnedHome,
  });

  /// Provider results for a file not in the library yet (the poster of
  /// the guess, «Не то»): `kind` is `movie`, `show` or `anime`. Writes
  /// nothing.
  Future<List<CoreMatchCandidate>> uploadSearch({
    required CoreMetadataSettings settings,
    required String kind,
    required String title,
    int? year,
  });

  /// Checks a parent PIN (of any profile without restrictions); a right
  /// one returns a parent token for the management calls. Counted by the
  /// wrong-PIN backoff.
  Future<CorePinVerdict> verifyParentPin({required String pin});

  /// Checks the PIN of profile `id` (with `or_parent`, a parent PIN is
  /// right too). A profile without a PIN takes any. A parent PIN returns
  /// a parent token. Counted by the wrong-PIN backoff.
  Future<CorePinVerdict> verifyProfilePin({
    required PlatformInt64 id,
    required String pin,
    required bool orParent,
  });

  /// Versions of a movie or episode, best resolution first; the one the
  /// item plays has `is_default`.
  Future<List<CoreVersion>> versions({required String itemId});

  /// Saved preferences of a view, or its defaults.
  Future<CoreViewPrefs> viewPrefs({required String view});
}

/// An entry of "Continue watching".
class CoreContinueItem {
  final CoreItem item;
  final CoreProgress progress;

  /// Up Next: the episode after a finished one.
  final bool upNext;

  const CoreContinueItem({
    required this.item,
    required this.progress,
    required this.upNext,
  });

  @override
  int get hashCode => item.hashCode ^ progress.hashCode ^ upNext.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CoreContinueItem &&
          runtimeType == other.runtimeType &&
          item == other.item &&
          progress == other.progress &&
          upNext == other.upNext;
}

/// What [`CoreLibrary::import_v0`] did.
class CoreImportReport {
  final int sources;
  final int files;
  final int matched;
  final int progress;

  /// Progress waiting for its file's fingerprint (LIB-015).
  final int progressPending;
  final int progressSkipped;
  final int itemsSkipped;

  /// Which source each v0 source became: the app moves the SMB passwords
  /// it kept under v0 ids (LIB-015).
  final List<CoreV0Source> v0Sources;

  const CoreImportReport({
    required this.sources,
    required this.files,
    required this.matched,
    required this.progress,
    required this.progressPending,
    required this.progressSkipped,
    required this.itemsSkipped,
    required this.v0Sources,
  });

  @override
  int get hashCode =>
      sources.hashCode ^
      files.hashCode ^
      matched.hashCode ^
      progress.hashCode ^
      progressPending.hashCode ^
      progressSkipped.hashCode ^
      itemsSkipped.hashCode ^
      v0Sources.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CoreImportReport &&
          runtimeType == other.runtimeType &&
          sources == other.sources &&
          files == other.files &&
          matched == other.matched &&
          progress == other.progress &&
          progressPending == other.progressPending &&
          progressSkipped == other.progressSkipped &&
          itemsSkipped == other.itemsSkipped &&
          v0Sources == other.v0Sources;
}

/// A movie, show, episode or track.
class CoreItem {
  /// `m<work>`, `s<work>`, `e<episode>` or `t<track>`.
  final String id;
  final CoreItemKind kind;
  final String title;
  final String? originalTitle;
  final int? year;
  final String? overview;

  /// Episodes: id of the show item.
  final String? showId;
  final int? season;
  final int? episode;
  final String? artist;
  final String? album;
  final int? trackNumber;
  final PlatformInt64 sourceId;

  /// Path relative to the source root (shows: the show folder).
  final String relPath;

  /// Absolute path for local sources.
  final String? localPath;
  final PlatformInt64? durationMs;
  final double? matchConfidence;
  final PlatformInt64? tmdbId;
  final PlatformInt64? addedAtMs;

  /// Poster URL (https or `file://`); episodes: the show's.
  final String? posterUrl;

  /// Backdrop URL; episodes: the episode still.
  final String? backdropUrl;

  /// Local poster or album cover next to the files, relative to the
  /// source root like `rel_path` (LIB-007 groups; episodes: the show's).
  /// Network sources: fetch it through [`CoreLibrary::stream_base_url`].
  final String? localPoster;

  /// Versions of a movie or episode (LIB-010): 2+ shows a version picker
  /// on play ([`CoreLibrary::versions`]). 1 for shows and tracks.
  final int versionCount;

  /// Why the player cannot play the item's file, `None` if it can
  /// (LIB-017, LIB-020): a stable code (`disc_image`) the app translates.
  /// The app shows the reason instead of opening the player.
  final String? unplayable;

  const CoreItem({
    required this.id,
    required this.kind,
    required this.title,
    this.originalTitle,
    this.year,
    this.overview,
    this.showId,
    this.season,
    this.episode,
    this.artist,
    this.album,
    this.trackNumber,
    required this.sourceId,
    required this.relPath,
    this.localPath,
    this.durationMs,
    this.matchConfidence,
    this.tmdbId,
    this.addedAtMs,
    this.posterUrl,
    this.backdropUrl,
    this.localPoster,
    required this.versionCount,
    this.unplayable,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      kind.hashCode ^
      title.hashCode ^
      originalTitle.hashCode ^
      year.hashCode ^
      overview.hashCode ^
      showId.hashCode ^
      season.hashCode ^
      episode.hashCode ^
      artist.hashCode ^
      album.hashCode ^
      trackNumber.hashCode ^
      sourceId.hashCode ^
      relPath.hashCode ^
      localPath.hashCode ^
      durationMs.hashCode ^
      matchConfidence.hashCode ^
      tmdbId.hashCode ^
      addedAtMs.hashCode ^
      posterUrl.hashCode ^
      backdropUrl.hashCode ^
      localPoster.hashCode ^
      versionCount.hashCode ^
      unplayable.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CoreItem &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          kind == other.kind &&
          title == other.title &&
          originalTitle == other.originalTitle &&
          year == other.year &&
          overview == other.overview &&
          showId == other.showId &&
          season == other.season &&
          episode == other.episode &&
          artist == other.artist &&
          album == other.album &&
          trackNumber == other.trackNumber &&
          sourceId == other.sourceId &&
          relPath == other.relPath &&
          localPath == other.localPath &&
          durationMs == other.durationMs &&
          matchConfidence == other.matchConfidence &&
          tmdbId == other.tmdbId &&
          addedAtMs == other.addedAtMs &&
          posterUrl == other.posterUrl &&
          backdropUrl == other.backdropUrl &&
          localPoster == other.localPoster &&
          versionCount == other.versionCount &&
          unplayable == other.unplayable;
}

/// Kind of a library item.
enum CoreItemKind {
  movie,

  /// A show or an anime series (`show` is a Dart keyword).
  series,
  episode,
  track,
}

/// Settings of a metadata run.
class CoreMetadataSettings {
  /// The user's own TMDB key (v3 key or v4 token); `None` uses the key
  /// built into the app, if any. Without any key only anime is matched
  /// (AniList, Shikimori).
  final String? tmdbApiKey;

  /// The user's own TheTVDB key (META-012): TheTVDB is asked only with
  /// it; `None`: TheTVDB is off.
  final String? tvdbApiKey;

  /// TheTVDB subscriber PIN, for keys that need one; `None` for keys from
  /// a person's own API dashboard.
  final String? tvdbPin;

  /// The user's personal Fanart.tv key (META-012), sent with the build's
  /// project key (or alone without one); `None` uses the project key.
  final String? fanartApiKey;

  /// Metadata language, e.g. `ru-RU` or `en-US`.
  final String language;

  /// Directory of the provider response cache (`provider-cache.sqlite`);
  /// disposable, so the platform cache directory.
  final String cacheDir;

  /// The anime-offline-database file shipped with the app (META-030),
  /// copied out of the assets by Dart; `None` without one.
  final String? animeDbBundled;

  /// Daily update of the anime databases from GitHub
  /// (anime-offline-database releases, the Anime-Lists list); off: only
  /// what the device already has is read (META-030 setting, on by
  /// default).
  final bool animeDataUpdates;

  /// Ask again at once for works whose last fetch failed (the network
  /// came back, LIB-024) instead of waiting for their retry time.
  final bool retryFailed;

  /// «Распознавать аниме по кадрам» (META-031): the user agreed that
  /// frames of anime the run could not recognise go to trace.moe. Off by
  /// default; off: no frame is read or sent.
  final bool animeFrameSearch;

  const CoreMetadataSettings({
    this.tmdbApiKey,
    this.tvdbApiKey,
    this.tvdbPin,
    this.fanartApiKey,
    required this.language,
    required this.cacheDir,
    this.animeDbBundled,
    required this.animeDataUpdates,
    required this.retryFailed,
    required this.animeFrameSearch,
  });

  @override
  int get hashCode =>
      tmdbApiKey.hashCode ^
      tvdbApiKey.hashCode ^
      tvdbPin.hashCode ^
      fanartApiKey.hashCode ^
      language.hashCode ^
      cacheDir.hashCode ^
      animeDbBundled.hashCode ^
      animeDataUpdates.hashCode ^
      retryFailed.hashCode ^
      animeFrameSearch.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CoreMetadataSettings &&
          runtimeType == other.runtimeType &&
          tmdbApiKey == other.tmdbApiKey &&
          tvdbApiKey == other.tvdbApiKey &&
          tvdbPin == other.tvdbPin &&
          fanartApiKey == other.fanartApiKey &&
          language == other.language &&
          cacheDir == other.cacheDir &&
          animeDbBundled == other.animeDbBundled &&
          animeDataUpdates == other.animeDataUpdates &&
          retryFailed == other.retryFailed &&
          animeFrameSearch == other.animeFrameSearch;
}

/// Stage of a metadata run (LIB-023).
enum CoreMetadataStage {
  /// Titles, posters and descriptions: local anime database and TMDB.
  titles,

  /// AniList and Shikimori for anime.
  anime,
}

/// Progress of [`CoreLibrary::fetch_metadata`]; the last update has
/// `done` set.
class CoreMetadataUpdate {
  /// Works decided (all stages).
  final int processed;

  /// Works of the run.
  final int total;
  final bool done;
  final int matched;
  final int notFound;
  final int failed;

  /// Why the run stopped early (rejected key, offline), or a failure.
  final String? error;
  final CoreMetadataStage stage;

  /// Works done in the current stage.
  final int stageDone;

  /// Works of the current stage.
  final int stageTotal;

  /// Providers that make the run wait at least a second.
  final List<CoreProviderWait> waiting;

  const CoreMetadataUpdate({
    required this.processed,
    required this.total,
    required this.done,
    required this.matched,
    required this.notFound,
    required this.failed,
    this.error,
    required this.stage,
    required this.stageDone,
    required this.stageTotal,
    required this.waiting,
  });

  @override
  int get hashCode =>
      processed.hashCode ^
      total.hashCode ^
      done.hashCode ^
      matched.hashCode ^
      notFound.hashCode ^
      failed.hashCode ^
      error.hashCode ^
      stage.hashCode ^
      stageDone.hashCode ^
      stageTotal.hashCode ^
      waiting.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CoreMetadataUpdate &&
          runtimeType == other.runtimeType &&
          processed == other.processed &&
          total == other.total &&
          done == other.done &&
          matched == other.matched &&
          notFound == other.notFound &&
          failed == other.failed &&
          error == other.error &&
          stage == other.stage &&
          stageDone == other.stageDone &&
          stageTotal == other.stageTotal &&
          waiting == other.waiting;
}

/// What recognition still owes (LIB-024, `pa_catalog::pending`).
class CorePendingWork {
  /// Videos the parser has not read yet (a scan was stopped).
  final BigInt unrecognizedFiles;

  /// Works the next metadata run takes.
  final BigInt worksWaiting;

  /// Of them: anime waiting for AniList / Shikimori.
  final BigInt animePending;

  /// Works whose last fetch failed, retried later.
  final BigInt worksFailed;

  /// Files whose headers are not read yet.
  final BigInt deferredProbes;

  /// Sources whose last scan never finished.
  final Int64List unfinishedScans;

  const CorePendingWork({
    required this.unrecognizedFiles,
    required this.worksWaiting,
    required this.animePending,
    required this.worksFailed,
    required this.deferredProbes,
    required this.unfinishedScans,
  });

  @override
  int get hashCode =>
      unrecognizedFiles.hashCode ^
      worksWaiting.hashCode ^
      animePending.hashCode ^
      worksFailed.hashCode ^
      deferredProbes.hashCode ^
      unfinishedScans.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CorePendingWork &&
          runtimeType == other.runtimeType &&
          unrecognizedFiles == other.unrecognizedFiles &&
          worksWaiting == other.worksWaiting &&
          animePending == other.animePending &&
          worksFailed == other.worksFailed &&
          deferredProbes == other.deferredProbes &&
          unfinishedScans == other.unfinishedScans;
}

/// Playback state of an item.
class CoreProgress {
  final String itemId;
  final PlatformInt64 positionMs;

  /// 0 if unknown.
  final PlatformInt64 durationMs;
  final PlatformInt64 updatedAtMs;
  final bool watched;

  const CoreProgress({
    required this.itemId,
    required this.positionMs,
    required this.durationMs,
    required this.updatedAtMs,
    required this.watched,
  });

  @override
  int get hashCode =>
      itemId.hashCode ^
      positionMs.hashCode ^
      durationMs.hashCode ^
      updatedAtMs.hashCode ^
      watched.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CoreProgress &&
          runtimeType == other.runtimeType &&
          itemId == other.itemId &&
          positionMs == other.positionMs &&
          durationMs == other.durationMs &&
          updatedAtMs == other.updatedAtMs &&
          watched == other.watched;
}

/// A provider that makes the metadata run wait.
class CoreProviderWait {
  /// `tmdb`, `anilist` or `shikimori`.
  final String provider;

  /// Seconds until its next request, rounded up.
  final int seconds;

  /// The provider asked for it (HTTP 429, quota used up); otherwise our
  /// pacing under its published limit.
  final bool providerAsked;

  const CoreProviderWait({
    required this.provider,
    required this.seconds,
    required this.providerAsked,
  });

  @override
  int get hashCode =>
      provider.hashCode ^ seconds.hashCode ^ providerAsked.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CoreProviderWait &&
          runtimeType == other.runtimeType &&
          provider == other.provider &&
          seconds == other.seconds &&
          providerAsked == other.providerAsked;
}

/// Stage of a scan.
enum CoreScanPhase {
  connecting,
  scanning,

  /// Music tags, fingerprints, recognition.
  analyzing,
  done,
}

/// What a running scan does right now (LIB-023), for an honest progress
/// line: the step and the counts within it.
enum CoreScanStep {
  connecting,

  /// Listing folders; `files_found` grows.
  listing,
  musicTags,

  /// Discs, parts, extras, sidecars, NFO.
  folders,

  /// Durations and streams (headers only).
  probing,
  fingerprinting,

  /// Local recognition of new videos.
  recognizing,

  /// Orphans and the search index.
  finishing,
  done,
}

/// Progress of [`CoreLibrary::scan`].
class CoreScanUpdate {
  final CoreScanPhase phase;
  final CoreScanStep step;
  final PlatformInt64? sourceId;
  final PlatformInt64 filesFound;
  final PlatformInt64 processed;
  final PlatformInt64? total;
  final String? currentPath;
  final String? error;

  /// Stable code of `error` (CORE-009): `not_found`, `unreachable`, `io`
  /// for a step of one source; a code of `LibraryError` when the whole
  /// scan failed.
  final String? errorCode;

  const CoreScanUpdate({
    required this.phase,
    required this.step,
    this.sourceId,
    required this.filesFound,
    required this.processed,
    this.total,
    this.currentPath,
    this.error,
    this.errorCode,
  });

  @override
  int get hashCode =>
      phase.hashCode ^
      step.hashCode ^
      sourceId.hashCode ^
      filesFound.hashCode ^
      processed.hashCode ^
      total.hashCode ^
      currentPath.hashCode ^
      error.hashCode ^
      errorCode.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CoreScanUpdate &&
          runtimeType == other.runtimeType &&
          phase == other.phase &&
          step == other.step &&
          sourceId == other.sourceId &&
          filesFound == other.filesFound &&
          processed == other.processed &&
          total == other.total &&
          currentPath == other.currentPath &&
          error == other.error &&
          errorCode == other.errorCode;
}

/// One group of [`CoreLibrary::search_grouped`].
class CoreSearchGroup {
  final CoreItemKind kind;

  /// Best first.
  final List<CoreItem> items;

  const CoreSearchGroup({required this.kind, required this.items});

  @override
  int get hashCode => kind.hashCode ^ items.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CoreSearchGroup &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          items == other.items;
}

/// A media source.
